  function getCubicPoint(points, t) {
    const [p0, p1, p2, p3] = points;
    const mt = 1 - t;
    const a = mt * mt * mt;
    const b = 3 * mt * mt * t;
    const c = 3 * mt * t * t;
    const d = t * t * t;
    return {
      x: a * p0[0] + b * p1[0] + c * p2[0] + d * p3[0],
      y: a * p0[1] + b * p1[1] + c * p2[1] + d * p3[1],
    };
  }

  function getAppChartRevenuePointFromSegments(svgX) {
    const segment =
      appChartRevenueSegments.find(
        (points) => svgX >= points[0][0] && svgX <= points[3][0],
      ) ||
      (svgX < appChartRevenueSegments[0][0][0]
        ? appChartRevenueSegments[0]
        : appChartRevenueSegments[appChartRevenueSegments.length - 1]);
    let low = 0;
    let high = 1;

    for (let index = 0; index < 18; index += 1) {
      const mid = (low + high) / 2;
      const point = getCubicPoint(segment, mid);
      if (point.x < svgX) {
        low = mid;
      } else {
        high = mid;
      }
    }

    return getCubicPoint(segment, (low + high) / 2);
  }

  function getAppChartRevenuePoint(svgX) {
    const path = appChartOverlay?.querySelector(".app-chart-line-live");
    if (!path?.getTotalLength) {
      return getAppChartRevenuePointFromSegments(svgX);
    }

    const total = path.getTotalLength();
    let low = 0;
    let high = total;

    for (let index = 0; index < 18; index += 1) {
      const mid = (low + high) / 2;
      const point = path.getPointAtLength(mid);
      if (point.x < svgX) {
        low = mid;
      } else {
        high = mid;
      }
    }

    return path.getPointAtLength((low + high) / 2);
  }

  function getNearestAppChartMonth(svgX) {
    return appChartHoverData.reduce((best, item) => {
      if (!best || Math.abs(item.x - svgX) < Math.abs(best.x - svgX)) {
        return item;
      }
      return best;
    }, null);
  }

  function updateAppChartHover(event) {
    if (!appPreview || !appChartOverlay) {
      return;
    }

    const chartStage = appChartOverlay.querySelector(".app-chart-stage");
    const stageRect = chartStage?.getBoundingClientRect();
    const stageWidth = chartStage?.offsetWidth || 408;
    const stageScaleX =
      stageRect && stageWidth ? stageRect.width / Math.max(1, stageWidth) : 1;
    const svgWidth = 370;
    const plotLeft = 36;
    const plotTop =
      parseFloat(
        getComputedStyle(appChartOverlay).getPropertyValue("--chart-plot-top"),
      ) || 22;
    const plotWidth = 370;
    const leftBound = 0;
    const rightBound = 370;
    const fallbackSvgX = 165.114;
    const svgX =
      event && stageRect
        ? clamp(
            (((event.clientX - stageRect.left) / Math.max(0.001, stageScaleX) -
              plotLeft) /
              Math.max(1, plotWidth)) *
              svgWidth,
            leftBound,
            rightBound,
          )
        : fallbackSvgX;
    const revenuePoint = getAppChartRevenuePoint(svgX);
    const targetProgress = (svgX - leftBound) / (rightBound - leftBound);
    const targetY =
      plotTop + 67.5588 + (35.7056 - 67.5588) * clamp(targetProgress, 0, 1);
    const dotRadius = 4;
    const chartX = clamp(
      plotLeft + (svgX / svgWidth) * plotWidth,
      plotLeft + dotRadius,
      plotLeft + plotWidth - dotRadius,
    );
    const revenueY = plotTop + revenuePoint.y;
    const cardWidth = 112;
    const cardX = clamp(
      chartX + 16,
      40,
      Math.max(40, stageWidth - cardWidth - 4),
    );
    const cardY = clamp(Math.min(revenueY, targetY) - 40, 10, 92);
    const nearest = getNearestAppChartMonth(svgX) || appChartHoverData[5];

    appChartOverlay.style.setProperty(
      "--chart-hover-x",
      `${chartX.toFixed(1)}px`,
    );
    appChartOverlay.style.setProperty(
      "--chart-hover-revenue-y",
      `${revenueY.toFixed(1)}px`,
    );
    appChartOverlay.style.setProperty(
      "--chart-hover-target-y",
      `${targetY.toFixed(1)}px`,
    );
    appChartOverlay.style.setProperty(
      "--chart-card-x",
      `${cardX.toFixed(1)}px`,
    );
    appChartOverlay.style.setProperty(
      "--chart-card-y",
      `${cardY.toFixed(1)}px`,
    );
    appChartOverlay
      .querySelector(".app-chart-hover-card b")
      ?.replaceChildren(nearest.month);
    const values = appChartOverlay.querySelectorAll(
      ".app-chart-hover-card strong",
    );
    values[0]?.replaceChildren(`$${nearest.target}K`);
    values[1]?.replaceChildren(`$${nearest.revenue}K`);
  }

  function buildAppRevealTypographyTokens(settings, tileDuration) {
    const textTargets = [
      ".app-header h2",
      ".app-header p",
      ".metric-card p",
      ".metric-card strong",
      ".panel-title h3",
      ".region-panel h3",
      ".region-row span",
    ];
    const previewRect = appPreview.getBoundingClientRect();
    const scaleX = previewRect.width / Math.max(1, appPreview.offsetWidth);
    const scaleY = previewRect.height / Math.max(1, appPreview.offsetHeight);
    const cornerPoint = getRevealOriginPoint(settings);
    const duration = Math.max(0, Number(settings.duration || 980));

    appPreview
      .querySelectorAll(textTargets.join(","))
      .forEach((target, index) => {
        if (index > 28) {
          return;
        }
        const rect = target.getBoundingClientRect();
        const centerX =
          (rect.left + rect.width / 2 - previewRect.left) /
          Math.max(1, previewRect.width);
        const centerY =
          (rect.top + rect.height / 2 - previewRect.top) /
          Math.max(1, previewRect.height);
        const distance =
          Math.sqrt(
            (centerX - cornerPoint.column) ** 2 +
              (centerY - cornerPoint.row) ** 2,
          ) / (cornerPoint.maxDistance || Math.SQRT2);
        const token = document.createElement("span");
        const delay = distance * Math.max(0, duration - tileDuration) + 40;

        token.className = "app-reveal-type-token";
        token.style.left = `${((rect.left - previewRect.left) / scaleX).toFixed(1)}px`;
        token.style.top = `${((rect.top - previewRect.top) / scaleY).toFixed(1)}px`;
        token.style.width = `${Math.max(24, rect.width / scaleX).toFixed(1)}px`;
        token.style.animationDelay = `${delay.toFixed(1)}ms`;
        token.style.animationDuration = `${Math.max(160, tileDuration * 0.72).toFixed(1)}ms`;
        token.textContent =
          index % 3 === 0
            ? "[font:mono->inter]"
            : index % 3 === 1
              ? "[color:lock]"
              : "[type:resolve]";
        appRevealOverlay.append(token);
      });
  }

  function clearAppReveal({ preserveBootFrame = false } = {}) {
    appPreview.classList.remove(
      "app-reveal-running",
      "app-reveal-fading",
      "is-section-reveal-gated",
      "reveal-target-prototype",
      "reveal-target-polished",
      "reveal-colorWave",
      "reveal-pixelTiles",
      "reveal-pixelate",
      "reveal-scanSweep",
      "reveal-crtBloom",
    );
    if (!preserveBootFrame) {
      appPreview.classList.remove("app-boot-clip-enabled");
    }
    if (preserveBootFrame) {
      clearAppRevealOverlayNodes();
    } else {
      appRevealOverlay.replaceChildren();
    }
  }

  function setAppRevealCompleteTarget(revealsPolished) {
    appPreview.classList.remove(
      "app-reveal-running",
      "app-reveal-fading",
      "is-section-reveal-gated",
      "reveal-target-prototype",
      "reveal-target-polished",
      "reveal-colorWave",
      "reveal-pixelTiles",
      "reveal-pixelate",
      "reveal-scanSweep",
      "reveal-crtBloom",
    );
    appPreview.classList.remove("app-boot-clip-enabled");
    appRevealOverlay.replaceChildren();
    appPreview.classList.add("is-visible", "is-image-backed");
    appPreview.classList.toggle("is-wire", !revealsPolished);
    appPreview.classList.toggle("is-polished", revealsPolished);
    appPreview.classList.toggle("is-prototype-visible", !revealsPolished);
    if (revealsPolished) {
      updateAppChartHover();
    }
  }

  function triggerAppReveal(
    mode = "polished",
    state = currentState,
    { preserveBootFrame = false } = {},
  ) {
    const revealSettings = getAppRevealSettings(state);
    const revealsPolished = mode === "polished";
    clearAppReveal({ preserveBootFrame });

    if (revealSettings.preset === "none" || revealSettings.intensity <= 0) {
      setAppRevealCompleteTarget(revealsPolished);
      return 0;
    }

    setRootVar("--app-reveal-duration", `${revealSettings.duration}ms`);
    setRootVar("--app-reveal-strength", revealSettings.intensity);
    setRootVar(
      "--app-reveal-alpha",
      Math.min(0.95, 0.25 + revealSettings.intensity * 0.07).toFixed(2),
    );
    setRootVar(
      "--app-reveal-image",
      revealsPolished
        ? 'url("/img/home/hero/app-done.png")'
        : 'url("/img/home/hero/app-prototype.png")',
    );
    setRootVar(
      "--app-reveal-line-rgb",
      rgbTupleFromColor(revealSettings.lineColor, "#63f1ff"),
    );
    const lineDirection =
      revealSettings.lineDirection === "horizontal" ? "horizontal" : "vertical";
    setRootVar(
      "--app-reveal-line-angle",
      lineDirection === "horizontal" ? "0deg" : "90deg",
    );
    setRootVar(
      "--app-reveal-shadow-line-angle",
      lineDirection === "horizontal" ? "90deg" : "0deg",
    );
    setRootVar(
      "--app-reveal-line-opacity",
      clamp(Number(revealSettings.lineOpacity ?? 0.72), 0, 1).toFixed(2),
    );
    setRootVar(
      "--app-reveal-line-glow",
      `${Math.max(0, Number(revealSettings.lineGlow ?? 18)).toFixed(1)}px`,
    );
    setRootVar(
      "--app-reveal-line-hold",
      `${Math.max(0, Number(revealSettings.lineHold ?? 280)).toFixed(1)}ms`,
    );
    setRootVar(
      "--app-reveal-line-fade",
      `${Math.max(80, Number(revealSettings.lineFade ?? 520)).toFixed(1)}ms`,
    );
    appPreview.classList.add(
      `reveal-${revealSettings.preset}`,
      revealsPolished ? "reveal-target-polished" : "reveal-target-prototype",
    );

    appPreview.classList.add("is-wire", "is-image-backed");
    appPreview.classList.toggle("is-polished", false);
    appPreview.classList.toggle("is-prototype-visible", revealsPolished);

    if (revealSettings.preset === "colorWave") {
      buildAppColorWave(revealSettings, {
        preserveExisting: preserveBootFrame,
        includeChart: revealsPolished,
      });
    } else if (revealSettings.preset === "pixelTiles") {
      buildAppRevealPixels(revealSettings, {
        preserveExisting: preserveBootFrame,
      });
    }

    appPreview.classList.add("app-reveal-running");
    void appPreview.offsetWidth;
    const lineFadeTail =
      Math.max(0, Number(revealSettings.lineHold ?? 280)) +
      Math.max(80, Number(revealSettings.lineFade ?? 520));
    const cleanupDelay = Math.max(
      Number(revealSettings.duration || 0),
      Number(revealSettings.duration || 0) + lineFadeTail * 0.62,
    );
    const finalFadeDuration = 0;
    setRootVar("--app-reveal-final-fade", `${finalFadeDuration.toFixed(1)}ms`);

    window.setTimeout(() => {
      setAppRevealCompleteTarget(revealsPolished);
    }, cleanupDelay + finalFadeDuration);
    return Math.max(0, cleanupDelay + finalFadeDuration);
  }

  function getAppRevealDuration(revealSettings = getAppRevealSettings(5)) {
    if (
      revealSettings.preset === "none" ||
      Number(revealSettings.intensity || 0) <= 0
    ) {
      return 0;
    }

    return Math.max(0, Number(revealSettings.duration || 0));
  }

  function getAppRevealTotalDuration(revealSettings = getAppRevealSettings(5)) {
    const revealDuration = getAppRevealDuration(revealSettings);
    if (revealDuration <= 0) {
      return 0;
    }

    const lineFadeTail =
      Math.max(0, Number(revealSettings.lineHold ?? 280)) +
      Math.max(80, Number(revealSettings.lineFade ?? 520));
    return Math.max(revealDuration, revealDuration + lineFadeTail * 0.62);
  }

  async function playAppReveal(token, mode = "polished", state = currentState) {
    const duration = triggerAppReveal(mode, state);
    if (duration > 0) {
      await wait(duration + 260, token);
    }
    setAppRevealCompleteTarget(mode === "polished");
  }

  appChartOverlay?.addEventListener("pointermove", (event) => {
    updateAppChartHover(event);
  });

  appPreview?.addEventListener("pointermove", (event) => {
    if (
      !appPreview.classList.contains("is-image-backed") ||
      !appPreview.classList.contains("is-polished")
    ) {
      return;
    }

    const chartStage = appChartOverlay?.querySelector(".app-chart-stage");
    if (!chartStage) {
      return;
    }

    const rect = chartStage.getBoundingClientRect();
    const overlayRect = appChartOverlay.getBoundingClientRect();
    const insideOverlay =
      event.clientX >= overlayRect.left &&
      event.clientX <= overlayRect.right &&
      event.clientY >= overlayRect.top &&
      event.clientY <= overlayRect.bottom;

    if (insideOverlay) {
      updateAppChartHover(event);
    }
  });

  function getActiveFxSettingsPresets() {
    normalizeGroupFxSettings();
    return groupGlitchSettings.activePresets
      .filter((preset) => fxPresetOrder.includes(preset))
      .sort((a, b) => {
        const aIndex = fxSettingsPanelOrder.indexOf(a);
        const bIndex = fxSettingsPanelOrder.indexOf(b);
        return (
          (aIndex < 0 ? Number.MAX_SAFE_INTEGER : aIndex) -
          (bIndex < 0 ? Number.MAX_SAFE_INTEGER : bIndex)
        );
      });
  }

  function syncGroupFxLayerOrder() {
    const orderedPresets = getActiveFxSettingsPresets();
    const layerKeys = fxSettingsPanelOrder;
    const scanlinesZ = "330";
    layerKeys.forEach((preset) => {
      setRootVar(
        `--fx-z-${preset}`,
        preset === "vignette"
          ? "300"
          : preset === "scanlines"
            ? scanlinesZ
            : "80",
      );
    });

    orderedPresets.forEach((preset, index) => {
      setRootVar(
        `--fx-z-${preset}`,
        preset === "vignette"
          ? "300"
          : preset === "scanlines"
            ? scanlinesZ
            : String(90 + (orderedPresets.length - index) * 10),
      );
    });
  }

  function shadeMapHash(seed) {
    let value = seed >>> 0;
    value ^= value << 13;
    value ^= value >>> 17;
    value ^= value << 5;
    return ((value >>> 0) % 100000) / 100000;
  }

  function syncShadeMapCells({
    active,
    cellX,
    cellY,
    rectWidth,
    rectHeight,
    count,
    randomness,
    flickerNoise,
    flickerScale,
    speed,
    smoothness,
    opacity,
  }) {
    if (!shadeMapOverlay) {
      return;
    }

    if (!active || count <= 0) {
      shadeMapOverlay.replaceChildren();
      lastShadeMapRenderKey = "off";
      return;
    }

    const columns = Math.max(
      1,
      Math.floor(STAGE_BASE_WIDTH / Math.max(1, cellX)),
    );
    const rows = Math.max(
      1,
      Math.floor(STAGE_BASE_HEIGHT / Math.max(1, cellY)),
    );
    const available = columns * rows;
    const cellCount = Math.max(1, Math.min(Math.round(count), available, 360));
    const renderKey = [
      columns,
      rows,
      cellCount,
      Math.round(rectWidth),
      Math.round(rectHeight),
      randomness.toFixed(2),
      flickerNoise.toFixed(2),
      flickerScale.toFixed(2),
      speed.toFixed(2),
      smoothness.toFixed(2),
      opacity.toFixed(2),
    ].join(":");

    if (
      renderKey === lastShadeMapRenderKey &&
      shadeMapOverlay.childElementCount === cellCount
    ) {
      return;
    }

    const cells = [];
    const used = new Set();
    const randomRatio = randomness / 10;
    const noiseRatio = flickerNoise / 10;
    const speedBase = speed <= 0 ? 999999 : 2.4 / speed;
    const highBase = clamp(opacity, 0, 1);
    const lowBase = highBase * clamp(0.72 - noiseRatio * 0.7, 0, 0.72);
    const midBase = highBase * clamp(0.55 + noiseRatio * 0.22, 0, 0.92);
    const timing =
      smoothness >= 9.75
        ? "linear"
        : `steps(${Math.max(1, Math.round(1 + smoothness * 1.7))}, end)`;

    for (let index = 0; index < cellCount; index += 1) {
      let slot = Math.floor(shadeMapHash(index * 92821 + 17) * available);
      while (used.has(slot)) {
        slot = (slot + 1) % available;
      }
      used.add(slot);

      const column = slot % columns;
      const row = Math.floor(slot / columns);
      const jitterX =
        (shadeMapHash(index * 31847 + 11) - 0.5) * cellX * randomRatio;
      const jitterY =
        (shadeMapHash(index * 51749 + 23) - 0.5) * cellY * randomRatio;
      const sizeJitterX =
        1 + (shadeMapHash(index * 71933 + 31) - 0.5) * randomRatio * 0.42;
      const sizeJitterY =
        1 + (shadeMapHash(index * 61357 + 37) - 0.5) * randomRatio * 0.42;
      const durationJitter =
        0.35 + shadeMapHash(index * 44131 + 43) * (1.3 + noiseRatio * 1.8);
      const phase =
        shadeMapHash(index * 67213 + 59) *
        speedBase *
        (2.5 + noiseRatio * 6 + flickerScale);
      const pulseSeed = shadeMapHash(index * 19937 + 61);
      const low = clamp(lowBase + (pulseSeed - 0.5) * noiseRatio * 0.22, 0, 1);
      const mid = clamp(
        midBase + (shadeMapHash(index * 45989 + 71) - 0.5) * noiseRatio * 0.24,
        low,
        1,
      );
      const high = clamp(
        highBase -
          shadeMapHash(index * 83561 + 83) * noiseRatio * highBase * 0.08,
        mid,
        1,
      );

      const cell = document.createElement("i");
      cell.className = "shade-map-cell";
      cell.style.left = `${column * cellX + jitterX}px`;
      cell.style.top = `${row * cellY + jitterY}px`;
      cell.style.width = `${Math.max(1, rectWidth * sizeJitterX)}px`;
      cell.style.height = `${Math.max(1, rectHeight * sizeJitterY)}px`;
      cell.dataset.centerX = (
        column * cellX +
        jitterX +
        (rectWidth * sizeJitterX) / 2
      ).toFixed(2);
      cell.dataset.centerY = (
        row * cellY +
        jitterY +
        (rectHeight * sizeJitterY) / 2
      ).toFixed(2);
      cell.style.animationDuration = `${speedBase * durationJitter}s`;
      cell.style.animationDelay = `${-phase}s`;
      cell.style.animationTimingFunction = timing;
      cell.style.setProperty("--shade-cell-low", low.toFixed(3));
      cell.style.setProperty("--shade-cell-mid", mid.toFixed(3));
      cell.style.setProperty("--shade-cell-high", high.toFixed(3));
      cells.push(cell);
    }

    shadeMapOverlay.replaceChildren(...cells);
    lastShadeMapRenderKey = renderKey;
    if (shadeMapEraseTarget) {
      scheduleShadeMapCursorErase();
    }
  }

  function clearShadeMapCursorErase() {
    shadeMapErasePointer = null;
    shadeMapEraseTarget = null;
    shadeMapEraseCurrent = null;
    if (shadeMapEraseFrame) {
      window.cancelAnimationFrame(shadeMapEraseFrame);
      shadeMapEraseFrame = 0;
    }
    shadeMapOverlay
      ?.querySelectorAll(".shade-map-cell.is-cursor-erased")
      .forEach((cell) => {
        cell.classList.remove("is-cursor-erased");
      });
  }

  function getShadeMapEraseCenter() {
    return { x: STAGE_BASE_WIDTH / 2, y: STAGE_BASE_HEIGHT / 2 };
  }

  function scheduleShadeMapCursorErase() {
    if (!shadeMapEraseFrame) {
      shadeMapEraseFrame = window.requestAnimationFrame(
        applyShadeMapCursorErase,
      );
    }
  }

  function getShadeMapErasePointFromEvent(event) {
    const rect = stage.getBoundingClientRect();
    return {
      x:
        ((event.clientX - rect.left) / Math.max(1, rect.width)) *
        STAGE_BASE_WIDTH,
      y:
        ((event.clientY - rect.top) / Math.max(1, rect.height)) *
        STAGE_BASE_HEIGHT,
    };
  }

  function returnShadeMapCursorEraseToCenter() {
    const config = getGroupFxConfig("shademap");
    if (!isGroupFxActive("shademap") || config.cursorErase === false) {
      clearShadeMapCursorErase();
      return;
    }

    shadeMapErasePointer = null;
    shadeMapEraseTarget = getShadeMapEraseCenter();
    shadeMapEraseCurrent ||= { ...shadeMapEraseTarget };
    scheduleShadeMapCursorErase();
  }

  function returnShadeMapCursorEraseToCenterWhenOutside(event) {
    const rect = stage.getBoundingClientRect();
    const isInside =
      event.clientX >= rect.left &&
      event.clientX <= rect.right &&
      event.clientY >= rect.top &&
      event.clientY <= rect.bottom;

    if (!isInside) {
      returnShadeMapCursorEraseToCenter();
    }
  }

  function applyShadeMapCursorErase() {
    shadeMapEraseFrame = 0;
    const config = getGroupFxConfig("shademap");
    const active =
      isGroupFxActive("shademap") &&
      config.cursorErase !== false &&
      Number(config.intensity ?? 0) > 0 &&
      Number(config.opacity ?? 0) > 0 &&
      shadeMapEraseTarget;

    if (!shadeMapOverlay || !active) {
      clearShadeMapCursorErase();
      return;
    }

    const radius = Math.max(0, Number(config.cursorEraseRadius ?? 150));
    const fade = Math.max(0, Number(config.cursorEraseFade ?? 200));
    const strength = clamp(Number(config.cursorEraseStrength ?? 1), 0, 1);
    shadeMapEraseCurrent ||= { ...shadeMapEraseTarget };
    const dxTarget = shadeMapEraseTarget.x - shadeMapEraseCurrent.x;
    const dyTarget = shadeMapEraseTarget.y - shadeMapEraseCurrent.y;
    shadeMapEraseCurrent.x += dxTarget * 0.22;
    shadeMapEraseCurrent.y += dyTarget * 0.22;
    const x = shadeMapEraseCurrent.x;
    const y = shadeMapEraseCurrent.y;
    const radiusSq = radius * radius;

    setRootVar("--shade-map-cursor-fade", `${fade}ms`);
    setRootVar("--shade-map-cursor-erased-opacity", (1 - strength).toFixed(2));

    shadeMapOverlay.querySelectorAll(".shade-map-cell").forEach((cell) => {
      const centerX = Number(cell.dataset.centerX);
      const centerY = Number(cell.dataset.centerY);
      if (!Number.isFinite(centerX) || !Number.isFinite(centerY)) {
        return;
      }
      const dx = centerX - x;
      const dy = centerY - y;
      cell.classList.toggle("is-cursor-erased", dx * dx + dy * dy <= radiusSq);
    });

    if (dxTarget * dxTarget + dyTarget * dyTarget > 0.25) {
      scheduleShadeMapCursorErase();
    }
  }

  function updateShadeMapCursorErase(event) {
    const config = getGroupFxConfig("shademap");
    if (!isGroupFxActive("shademap") || config.cursorErase === false) {
      clearShadeMapCursorErase();
      return;
    }
    shadeMapErasePointer = event;
    shadeMapEraseTarget = getShadeMapErasePointFromEvent(event);
    shadeMapEraseCurrent ||= { ...shadeMapEraseTarget };
    scheduleShadeMapCursorErase();
  }

  function syncGlitchControl() {
    syncGroupFxLayerOrder();
    const primaryPreset = getPrimaryVisualFxPreset();
    const primaryConfig = getGroupFxConfig(primaryPreset);
    const intensity =
      primaryPreset === "rgbsplit"
        ? getRgbSplitMaxIntensity(primaryConfig)
        : (primaryConfig.intensity ?? 0);
    const detail = primaryConfig.detail ?? 0;
    const rawSpeed = primaryConfig.speed ?? 1;
    const speed = rawSpeed <= 0 ? 0 : Math.max(0.01, rawSpeed);
    const presetMultiplier =
      {
        off: 0,
        rgbsplit: 0.2,
        shademap: 0,
        rgbgrid: 0,
        scanlines: 0.26,
        parallax: 0,
        vignette: 0,
        perspective: 0,
      }[primaryPreset] ?? 0;

    stage.dataset.textFx = primaryPreset;
    setRootVar(
      "--text-glitch-x",
      `${Math.max(1, intensity) * presetMultiplier * Math.max(0.2, detail / 5)}px`,
    );
    setRootVar(
      "--text-glitch-y",
      `${Math.max(1, intensity) * 0.08 * Math.max(0.2, detail / 5)}px`,
    );
    setRootVar(
      "--text-glitch-rgb",
      `${Math.max(0.25, intensity) * 0.18 * Math.max(0.2, detail / 5)}px`,
    );
    setRootVar("--text-glitch-duration", `${primaryConfig.duration ?? 720}ms`);
    const rgbSplitConfig = getGroupFxConfig("rgbsplit");
    const rgbSplitLogoIntensity = getRgbSplitTargetIntensity(
      rgbSplitConfig,
      "logoIntensity",
    );
    const rgbSplitTextIntensity = getRgbSplitTargetIntensity(
      rgbSplitConfig,
      "textIntensity",
    );
    const rgbSplitWindowIntensity = getRgbSplitTargetIntensity(
      rgbSplitConfig,
      "windowIntensity",
    );
    const rgbSplitIntensity = getRgbSplitMaxIntensity(rgbSplitConfig);
    const rgbSplitSpeed =
      rgbSplitConfig.speed <= 0 ? 0 : Math.max(0.01, rgbSplitConfig.speed ?? 1);
    setRootVar(
      "--rgb-split-x",
      `${Math.max(0, rgbSplitConfig.splitX ?? 2.1)}px`,
    );
    setRootVar(
      "--rgb-split-y",
      `${Math.max(0, rgbSplitConfig.splitY ?? 0.4)}px`,
    );
    setRootVar(
      "--rgb-split-alpha",
      Math.min(0.92, Math.max(0, rgbSplitIntensity / 8)).toFixed(2),
    );
    setRootVar(
      "--rgb-split-logo-alpha",
      Math.min(0.92, Math.max(0, rgbSplitLogoIntensity / 8)).toFixed(2),
    );
    setRootVar(
      "--rgb-split-text-alpha",
      Math.min(0.92, Math.max(0, rgbSplitTextIntensity / 8)).toFixed(2),
    );
    setRootVar(
      "--rgb-split-window-alpha",
      Math.min(0.92, Math.max(0, rgbSplitWindowIntensity / 8)).toFixed(2),
    );
    setRootVar(
      "--rgb-split-color-a",
      rgbTupleFromColor(rgbSplitConfig.colorA, "#ff314a"),
    );
    setRootVar(
      "--rgb-split-color-b",
      rgbTupleFromColor(rgbSplitConfig.colorB, "#00e5ff"),
    );
    setRootVar(
      "--rgb-split-color-c",
      rgbTupleFromColor(rgbSplitConfig.colorC, "#465fff"),
    );
    setRootVar(
      "--rgb-split-duration",
      rgbSplitSpeed === 0
        ? "999999s"
        : `${Math.max(0.22, 1.4 / rgbSplitSpeed)}s`,
    );
    stage.classList.toggle(
      "fx-rgb-split",
      isGroupFxActive("rgbsplit") && rgbSplitIntensity > 0,
    );
    const shadeMapConfig = getGroupFxConfig("shademap");
    const shadeMapIntensity = Math.max(0, shadeMapConfig.intensity ?? 0);
    const shadeMapDetail = Math.max(0, shadeMapConfig.detail ?? 6);
    const shadeMapSpeed =
      shadeMapConfig.speed <= 0 ? 0 : Math.max(0.01, shadeMapConfig.speed ?? 1);
    const shadeMapSmoothness = clamp(
      Number(shadeMapConfig.smoothness ?? 0),
      0,
      10,
    );
    const shadeMapFlickerNoise = clamp(
      Number(shadeMapConfig.flickerNoise ?? 5),
      0,
      10,
    );
    const shadeMapFlickerScale = clamp(
      Number(shadeMapConfig.flickerScale ?? 1),
      0.25,
      5,
    );
    const shadeMapOpacity = Math.max(
      0,
      Math.min(1, shadeMapConfig.opacity ?? 0.58),
    );
    const shadeMapXDensity = clamp(
      Number(shadeMapConfig.xDensity ?? 18),
      2,
      80,
    );
    const shadeMapYDensity = clamp(
      Number(shadeMapConfig.yDensity ?? 18),
      2,
      80,
    );
    const shadeMapRectWidth = clamp(
      Number(shadeMapConfig.blockWidth ?? 210),
      1,
      720,
    );
    const shadeMapRectHeight = clamp(
      Number(shadeMapConfig.blockHeight ?? 34),
      1,
      360,
    );
    const shadeMapQuantity = clamp(
      Number(shadeMapConfig.quantity ?? 72),
      1,
      360,
    );
    const shadeMapRandomness = clamp(
      Number(shadeMapConfig.randomness ?? 3),
      0,
      10,
    );
    const shadeMapRandomnessRatio = shadeMapRandomness / 10;
    const shadeMapCellX = clamp(
      STAGE_BASE_WIDTH / shadeMapXDensity,
      4,
      STAGE_BASE_WIDTH,
    );
    const shadeMapCellY = clamp(
      STAGE_BASE_HEIGHT / shadeMapYDensity,
      4,
      STAGE_BASE_HEIGHT,
    );
    const shadeMapActive =
      isGroupFxActive("shademap") &&
      shadeMapIntensity > 0 &&
      shadeMapOpacity > 0;
    setRootVar("--shade-map-alpha", shadeMapActive ? "1" : "0");
    setRootVar(
      "--shade-map-detail",
      Math.max(0, shadeMapDetail / 10).toFixed(2),
    );
    setRootVar("--shade-map-density-x", shadeMapXDensity.toFixed(2));
    setRootVar("--shade-map-density-y", shadeMapYDensity.toFixed(2));
    setRootVar("--shade-map-quantity", shadeMapQuantity.toFixed(2));
    setRootVar("--shade-map-randomness", shadeMapRandomnessRatio.toFixed(2));
    setRootVar(
      "--shade-map-blur",
      `${Math.max(0, shadeMapConfig.blur ?? 12)}px`,
    );
    setRootVar("--shade-map-cell-x", `${shadeMapCellX}px`);
    setRootVar("--shade-map-cell-y", `${shadeMapCellY}px`);
    setRootVar("--shade-map-square-x", `${shadeMapRectWidth}px`);
    setRootVar("--shade-map-square-y", `${shadeMapRectHeight}px`);
    setRootVar(
      "--shade-map-cell-size",
      `${Math.max(8, Math.min(shadeMapRectWidth, shadeMapRectHeight))}px`,
    );
    setRootVar(
      "--shade-map-offset-a-x",
      `${17 + shadeMapRandomnessRatio * 83}px`,
    );
    setRootVar(
      "--shade-map-offset-a-y",
      `${9 + shadeMapRandomnessRatio * 41}px`,
    );
    setRootVar(
      "--shade-map-offset-b-x",
      `${(0.45 + shadeMapRandomnessRatio * 0.37).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-offset-b-y",
      `${(0.35 + shadeMapRandomnessRatio * 0.49).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-offset-c-x",
      `${(1.1 + shadeMapRandomnessRatio * 0.91).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-offset-c-y",
      `${(0.72 + shadeMapRandomnessRatio * 0.67).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-scale-b-x",
      `${(1.6 + shadeMapRandomnessRatio * 1.15).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-scale-b-y",
      `${(1.35 + shadeMapRandomnessRatio * 0.78).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-scale-c-x",
      `${(2.4 + shadeMapRandomnessRatio * 1.7).toFixed(2)}`,
    );
    setRootVar(
      "--shade-map-scale-c-y",
      `${(1.9 + shadeMapRandomnessRatio * 1.25).toFixed(2)}`,
    );
    setRootVar("--shade-map-flicker-scale", shadeMapFlickerScale.toFixed(2));
    setRootVar(
      "--shade-map-cursor-fade",
      `${Math.max(0, Number(shadeMapConfig.cursorEraseFade ?? 200))}ms`,
    );
    setRootVar(
      "--shade-map-cursor-erased-opacity",
      (
        1 - clamp(Number(shadeMapConfig.cursorEraseStrength ?? 1), 0, 1)
      ).toFixed(2),
    );
    setRootVar(
      "--shade-map-layer-a-alpha",
      shadeMapQuantity >= 1 ? "1.00" : "0.00",
    );
    setRootVar(
      "--shade-map-layer-b-alpha",
      clamp((shadeMapQuantity - 5) / 5, 0, 1).toFixed(2),
    );
    setRootVar(
      "--shade-map-flicker-a",
      shadeMapSpeed === 0
        ? "999999s"
        : `${Math.max(0.08, 1.45 / shadeMapSpeed)}s`,
    );
    setRootVar(
      "--shade-map-flicker-b",
      shadeMapSpeed === 0
        ? "999999s"
        : `${Math.max(0.06, 0.98 / shadeMapSpeed)}s`,
    );
    setRootVar(
      "--shade-map-color",
      rgbTupleFromColor(shadeMapConfig.color, "#ffffff"),
    );
    stage.classList.toggle("fx-shade-map", shadeMapActive);
    syncShadeMapCells({
      active: shadeMapActive,
      cellX: shadeMapCellX,
      cellY: shadeMapCellY,
      rectWidth: shadeMapRectWidth,
      rectHeight: shadeMapRectHeight,
      count: shadeMapQuantity,
      randomness: shadeMapRandomness,
      flickerNoise: shadeMapFlickerNoise,
      flickerScale: shadeMapFlickerScale,
      speed: shadeMapSpeed,
      smoothness: shadeMapSmoothness,
      opacity: shadeMapOpacity,
    });
    if (!shadeMapActive || shadeMapConfig.cursorErase === false) {
      clearShadeMapCursorErase();
    } else if (!shadeMapEraseTarget) {
      returnShadeMapCursorEraseToCenter();
    } else {
      scheduleShadeMapCursorErase();
    }
    const rgbGridConfig = getGroupFxConfig("rgbgrid");
    const rgbGridIntensity = Math.max(0, rgbGridConfig.intensity ?? 0);
    const rgbGridStripe = Math.max(0, rgbGridConfig.stripeHeight ?? 7);
    const rgbGridGap = Math.max(0, rgbGridConfig.stripeGap ?? 0);
    const rgbGridSpeed =
      rgbGridConfig.speed <= 0 ? 0 : Math.max(0.01, rgbGridConfig.speed ?? 0.4);
    const rgbGridOpacity = Math.max(
      0,
      Math.min(1, rgbGridConfig.opacity ?? 0.18),
    );
    const rgbGridActive =
      isGroupFxActive("rgbgrid") &&
      rgbGridIntensity > 0 &&
      rgbGridOpacity > 0 &&
      rgbGridStripe > 0;
    setRootVar("--rgb-grid-stripe", `${rgbGridStripe}px`);
    setRootVar("--rgb-grid-stop-2", `${rgbGridStripe * 2}px`);
    setRootVar("--rgb-grid-stop-3", `${rgbGridStripe * 3}px`);
    setRootVar(
      "--rgb-grid-cycle",
      `${Math.max(1, rgbGridStripe * 3 + rgbGridGap)}px`,
    );
    setRootVar(
      "--rgb-grid-softness",
      `${Math.max(0, rgbGridConfig.softness ?? 0)}px`,
    );
    setRootVar(
      "--rgb-grid-strength",
      Math.min(10, rgbGridIntensity).toFixed(2),
    );
    setRootVar(
      "--rgb-grid-opacity",
      rgbGridActive
        ? Math.min(
            1,
            rgbGridOpacity * Math.max(0.18, rgbGridIntensity / 6),
          ).toFixed(2)
        : "0",
    );
    setRootVar(
      "--rgb-grid-duration",
      rgbGridSpeed === 0 ? "999999s" : `${Math.max(0.5, 9 / rgbGridSpeed)}s`,
    );
    setRootVar(
      "--rgb-grid-red",
      rgbTupleFromColor(rgbGridConfig.redColor, "#2c070c"),
    );
    setRootVar(
      "--rgb-grid-green",
      rgbTupleFromColor(rgbGridConfig.greenColor, "#072614"),
    );
    setRootVar(
      "--rgb-grid-blue",
      rgbTupleFromColor(rgbGridConfig.blueColor, "#080c2d"),
    );
    stage.classList.toggle("fx-rgb-grid", rgbGridActive);
    const scanlineConfig = getGroupFxConfig("scanlines");
    const scanlineRawSpeed = scanlineConfig.speed ?? 1;
    const scanlineSpeed =
      scanlineRawSpeed <= 0 ? 0 : Math.max(0.01, scanlineRawSpeed);
    const overlayIntensity = Math.max(
      intensity,
      isGroupFxActive("scanlines") ? scanlineConfig.intensity : 0,
    );
    setRootVar(
      "--group-fx-alpha",
      Math.min(0.85, Math.max(0, overlayIntensity / 10)).toFixed(2),
    );
    setRootVar("--group-fx-detail", Math.max(0, detail / 10).toFixed(2));
    setRootVar("--group-fx-speed", speed.toFixed(2));
    setRootVar(
      "--group-fx-scan-duration",
      scanlineSpeed === 0
        ? "999999s"
        : `${Math.max(20, 166 / scanlineSpeed)}ms`,
    );
    setRootVar(
      "--group-fx-bar-duration",
      scanlineSpeed === 0 ? "999999s" : `${Math.max(0.3, 2 / scanlineSpeed)}s`,
    );
    const scanlineThickness = scanlineConfig.thickness ?? 2;
    const scanlineSpacing = scanlineConfig.spacing ?? 3;
    const scanlineDetail = scanlineConfig.detail ?? 6;
    setRootVar("--scanline-thickness", `${scanlineThickness}px`);
    setRootVar("--scanline-spacing", `${scanlineSpacing}px`);
    setRootVar(
      "--scanline-step",
      `${Math.max(1, scanlineThickness + scanlineSpacing)}px`,
    );
    setRootVar(
      "--scanline-line-alpha",
      scanlineThickness <= 0
        ? "0"
        : Math.max(0, scanlineDetail / 10).toFixed(2),
    );
    setRootVar("--scanline-bar-height", `${scanlineConfig.barHeight ?? 180}%`);
    setRootVar(
      "--scanline-sweep-opacity",
      Math.max(0, Math.min(1, scanlineConfig.sweepOpacity ?? 0.42)).toFixed(2),
    );
    setRootVar(
      "--scanline-sweep-glow",
      Math.max(0, Math.min(1, scanlineConfig.sweepGlow ?? 0.2)).toFixed(2),
    );
    setRootVar(
      "--scanline-sweep-shadow",
      Math.max(0, Math.min(1, scanlineConfig.sweepShadow ?? 0.28)).toFixed(2),
    );
    setRootVar(
      "--scanline-sweep-softness",
      `${Math.max(0, Math.min(80, scanlineConfig.sweepSoftness ?? 24))}%`,
    );
    setRootVar("--scanline-direction", scanlineConfig.reverse ? -1 : 1);
    stage.classList.toggle(
      "fx-scanlines",
      isGroupFxActive("scanlines") && scanlineConfig.intensity > 0,
    );
    stage.classList.remove("text-glitch-loop");
    const vignetteConfig = getGroupFxConfig("vignette");
    const vignetteHardOpacityRaw = Math.max(
      0,
      Math.min(1, vignetteConfig.hardOpacity ?? 0.38),
    );
    const vignetteActive =
      isGroupFxActive("vignette") &&
      vignetteConfig.intensity > 0 &&
      ((vignetteConfig.opacity ?? 0) > 0 || vignetteHardOpacityRaw > 0);
    const vignetteOpacity = vignetteActive
      ? Math.min(
          1,
          Math.max(0, vignetteConfig.opacity ?? 0.38) *
            Math.max(0.15, Math.min(1, (vignetteConfig.intensity ?? 4) / 6)),
        )
      : 0;
    const vignetteHardOpacity = vignetteActive ? vignetteHardOpacityRaw : 0;
    const fallbackVignetteEdge = Math.max(0, vignetteConfig.edge ?? 180);
    const vignetteTop = Math.max(0, vignetteConfig.top ?? fallbackVignetteEdge);
    const vignetteRight = Math.max(
      0,
      vignetteConfig.right ?? fallbackVignetteEdge,
    );
    const vignetteBottom = Math.max(
      0,
      vignetteConfig.bottom ?? fallbackVignetteEdge,
    );
    const vignetteLeft = Math.max(
      0,
      vignetteConfig.left ?? fallbackVignetteEdge,
    );
    setRootVar("--screen-vignette-opacity", vignetteOpacity.toFixed(2));
    setRootVar(
      "--screen-vignette-hard-opacity",
      vignetteHardOpacity.toFixed(2),
    );
    setRootVar("--screen-vignette-top", `${vignetteTop}px`);
    setRootVar(
      "--screen-vignette-top-mid",
      `${Math.round(vignetteTop * 0.35)}px`,
    );
    setRootVar("--screen-vignette-right", `${vignetteRight}px`);
    setRootVar(
      "--screen-vignette-right-mid",
      `${Math.round(vignetteRight * 0.35)}px`,
    );
    setRootVar("--screen-vignette-bottom", `${vignetteBottom}px`);
    setRootVar(
      "--screen-vignette-bottom-mid",
      `${Math.round(vignetteBottom * 0.35)}px`,
    );
    setRootVar("--screen-vignette-left", `${vignetteLeft}px`);
    setRootVar(
      "--screen-vignette-left-mid",
      `${Math.round(vignetteLeft * 0.35)}px`,
    );
    setRootVar(
      "--screen-vignette-radius",
      `${Math.max(0, vignetteConfig.roundness ?? 28)}px`,
    );
    setRootVar(
      "--screen-vignette-blur",
      `${Math.max(0, vignetteConfig.blur ?? 18)}px`,
    );
    setRootVar(
      "--screen-vignette-color",
      rgbTupleFromColor(vignetteConfig.color, "#000000"),
    );
    const perspectiveConfig = getGroupFxConfig("perspective");
    const perspectiveTiltX = Number(
      perspectiveConfig.tiltX ?? perspectiveConfig.tilt ?? 0,
    );
    const perspectiveTiltY = Number(
      perspectiveConfig.tiltY ?? perspectiveConfig.tilt ?? 0,
    );
    const perspectiveShiftX = Number(
      perspectiveConfig.shiftX ?? perspectiveConfig.shift ?? 0,
    );
    const perspectiveShiftY = Number(
      perspectiveConfig.shiftY ?? perspectiveConfig.shift ?? 0,
    );
    const perspectiveWindowLift = Number(perspectiveConfig.windowLift ?? 0);
    const perspectiveActive =
      isGroupFxActive("perspective") &&
      Number(perspectiveConfig.intensity ?? 0) > 0 &&
      Math.abs(perspectiveTiltX) +
        Math.abs(perspectiveTiltY) +
        Math.abs(perspectiveShiftX) +
        Math.abs(perspectiveShiftY) +
        Math.abs(perspectiveWindowLift) >
        0;
    stage.classList.toggle("fx-perspective", perspectiveActive);
    if (perspectiveActive) {
      schedulePerspectiveFrame();
    } else {
      setPerspectiveVars();
    }
    syncGridLayer();
  }

  function triggerTextGlitch({ force = false } = {}) {
    syncGlitchControl();
    stage.classList.remove("text-glitch-burst");
  }

  function getPlayerRuntimeFlags() {
    const features = window.DATABRICKS_USED_FEATURES || {};
    return {
      parallax: Boolean(features.parallax && isGroupFxActive("parallax")),
      perspective: Boolean(
        features.perspective && isGroupFxActive("perspective"),
      ),
    };
  }

  function scheduleRenderFrame(delay = RENDER_FRAME_MS) {
    if (viewportPaused) {
      return;
    }

    if (renderFrameTimer) {
      return;
    }

    const runtimeFlags = getPlayerRuntimeFlags();
    if (!runtimeFlags.parallax && !runtimeFlags.perspective) {
      return;
    }

    renderFrameTimer = window.setTimeout(
      () => {
        renderFrameTimer = 0;
        drawGrid(performance.now());
      },
      Math.max(0, delay),
    );
  }

  function drawGrid(timestamp) {
    if (viewportPaused) {
      return;
    }

    const runtimeFlags = getPlayerRuntimeFlags();
    if (!runtimeFlags.parallax && !runtimeFlags.perspective) {
      if (gridWasVisible && gridCtx) {
        const { width, height } = resizeGridCanvas();
        gridCtx.clearRect(0, 0, width, height);
        gridWasVisible = false;
        lastGridRenderKey = "off";
      }
      return;
    }

    const frameTimestamp = timestamp || performance.now();
    if (
      lastRenderTickAt &&
      frameTimestamp - lastRenderTickAt < RENDER_FRAME_MS - 0.6
    ) {
      scheduleRenderFrame(
        RENDER_FRAME_MS - (frameTimestamp - lastRenderTickAt),
      );
      return;
    }
    lastRenderTickAt = lastRenderTickAt
      ? frameTimestamp - ((frameTimestamp - lastRenderTickAt) % RENDER_FRAME_MS)
      : frameTimestamp;

    updateParallaxFrame();
    updatePerspectiveFrame();
    if (gridWasVisible && gridCtx) {
      const { width, height } = resizeGridCanvas();
      gridCtx.clearRect(0, 0, width, height);
      gridWasVisible = false;
      lastGridRenderKey = "off";
    } else if (gridCanvasDirty) {
      resizeGridCanvas();
    }

    scheduleRenderFrame(RENDER_FRAME_MS);
  }

